"""Shipment records."""


class Shipment:
    def __init__(self, route, weight):
        self.route = route
        self.weight = weight

    def __repr__(self):
        return "Shipment(%r, %r)" % (self.route, self.weight)


ROWS = [('r22', 38), ('r10', 23), ('r22', 10), ('r22', 14), ('r22', 15)]


def load_shipments():
    """Yield the stored shipments one at a time."""
    for route, weight in ROWS:
        yield Shipment(route, weight)

