"""A book of shipments with a cached total."""


class ShipmentBook:
    def __init__(self):
        self._shipments = []
        self._total = None

    def add(self, shipment):
        """Add one shipment to the book."""
        self._shipments.append(shipment)

    def total(self):
        """Return the total weight of the shipments in the book."""
        if self._total is None:
            self._total = sum(x.weight for x in self._shipments)
        return self._total

    def count(self):
        """Return how many shipments the book holds."""
        return len(self._shipments)


def describe_shipment(shipment):
    """Return a one-line description of a shipment."""
    return "%s: %s" % (shipment.route, shipment.weight)

